	if _, err := s.AddFeeding("feed-fmt", "B1", "M1", "1.0", t1, "张三"); !errors.Is(err, ErrRequestConflict) {
		t.Fatalf("1.000 改成数值相等的 1.0 应返回 ErrRequestConflict，得到 %v", err)
	}

