	if err != nil {
		t.Fatalf("冲突后原内容应仍可重放: %v", err)
	}
	checkFeedingView(t, replayAgain, 1, "M1", "1", t1, "张三")

	// 批次始终只有首次那一笔投料，M1 累计实投为 1，没有被数值相等的
