func checkDuplicateRequestNos(data []byte) error {
    var probe struct {
        Requests json.RawMessage `json:"requests"`
    }
    if err := json.Unmarshal(data, &probe); err != nil {
        return nil // 解析错误由后续 json.Unmarshal 统一报告
    }
    raw := probe.Requests
    if len(raw) == 0 || string(raw) == "null" {
        return nil
    }
    dec := json.NewDecoder(bytes.NewReader(raw))
    tok, err := dec.Token()
    if err != nil {
        return nil
    }
    if d, ok := tok.(json.Delim); !ok || d != '{' {
        return nil // 非对象由后续解析/校验报告
    }
    seen := make(map[string]bool)
    for dec.More() {
        kt, err := dec.Token()
        if err != nil {
            return nil
        }
        key, ok := kt.(string)
        if !ok {
            return nil
        }
        if seen[key] {
            return fmt.Errorf("%w: 请求编号 %q 在台账中存在多份同编号请求记录", ErrCorruptData, key)
        }
        seen[key] = true
        var v json.RawMessage
        if err := dec.Decode(&v); err != nil {
            return nil
        }
    }
    return nil
}
